function generateGoClientMjs(): string {
  return `// scripts/generate-go-client.mjs — regenerates clients/go/client.go
// (a stdlib-only Go client) from the committed openapi.ai.yaml — the
// AI service's Python-generated spec (decision 9: the contract is the
// spine; here Python is the canonical side of the AI service's own
// contract). apps/api consumes this client through a local go.mod
// replace — it is the ONLY way apps/api talks to apps/ai (decision 5:
// never raw HTTP).
//
// The generator is intentionally small and dependency-light (only
// \`yaml\` for parsing): the emitted client is typed request/response
// structs plus one \`do\`-style request helper, nothing more.
// Regenerating must produce a byte-identical diff — the scaffold's
// tests assert that (test/generated-go.test.ts). The emitted structs
// are gofmt-aligned (name column, type column, tag column).
//
// Usage: node scripts/generate-go-client.mjs [spec-path] [out-dir]
//   spec-path defaults to ./openapi.ai.yaml
//   out-dir   defaults to ./clients/go

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import YAML from 'yaml';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const specPath = resolve(process.argv[2] ?? join(root, 'openapi.ai.yaml'));
const outDir = resolve(process.argv[3] ?? join(root, 'clients/go'));

const spec = YAML.parse(readFileSync(specPath, 'utf8'));

const header = [
  '// GENERATED by scripts/generate-go-client.mjs — do not edit by hand.',
  '// Regenerate with \`task contract:generate\` after regenerating',
  '// openapi.ai.yaml from the Python service (decision 9: Python is',
  '// the canonical side of the AI service contract).',
  '',
  'package aiclient',
  '',
  'import (',
  '\t"bytes"',
  '\t"context"',
  '\t"encoding/json"',
  '\t"fmt"',
  '\t"io"',
  '\t"net/http"',
  '\t"strings"',
  '\t"time"',
  ')',
  '',
].join('\\n');

// ---- type mapping ----------------------------------------------------------

// goType maps a JSON Schema to a Go type name. anyOf containing a
// 'null' variant is an optional field — the non-null variant's type is
// returned (pointer-ness is decided by the caller).
function goType(schema, schemas) {
  if (!schema) return 'any';
  if (schema.$ref) return schema.$ref.split('/').pop();
  if (schema.anyOf) {
    const nonNull = schema.anyOf.filter((s) => s.type !== 'null');
    if (nonNull.length === 1) return goType(nonNull[0], schemas);
    // Two non-null variants (e.g. string | string[]) is a union the
    // starter's typed client represents as the Go any.
    return 'any';
  }
  const t = schema.type;
  switch (t) {
    case 'string': return 'string';
    case 'integer': return 'int64';
    case 'number': return 'float64';
    case 'boolean': return 'bool';
    case 'array': return '[]' + goType(schema.items, schemas);
    case 'object': return 'map[string]any';
    default: return 'any';
  }
}

// isOptional reports whether a property may be absent on the wire: it
// is not in the required list and has no default (a default means the
// service always has a value to fall back to).
function isOptional(schema, required) {
  if (required) return false;
  if (schema.default !== undefined) return false;
  if (schema.anyOf) return schema.anyOf.some((s) => s.type === 'null');
  return true;
}

// fieldGoType returns the declared Go type for a property. Optional
// scalars and refs become pointers (nil = absent, omitted by
// omitempty); slices, maps, and unions stay value-typed.
function fieldGoType(schema, schemas, required) {
  const base = goType(schema, schemas);
  if (!isOptional(schema, required)) return base;
  if (base === 'any' || base.startsWith('[]') || base === 'map[string]any') return base;
  return '*' + base;
}

function goFieldName(prop) {
  // snake_case -> PascalCase ('tool_calls' -> 'ToolCalls').
  return prop.split('_').map((s) => s.charAt(0).toUpperCase() + s.slice(1)).join('');
}

function generateStructs(schemas) {
  const lines = [header];
  for (const [name, schema] of Object.entries(schemas)) {
    // FastAPI's default 422 validation schemas are plumbing, not part
    // of the AI service's primitive contract.
    if (name === 'HTTPValidationError' || name === 'ValidationError') continue;
    if (schema.type !== 'object') continue;
    if (schema.description) {
      for (const l of schema.description.split('\\n')) lines.push('// ' + l);
    }
    const fields = [];
    for (const [prop, propSchema] of Object.entries(schema.properties ?? {})) {
      const required = (schema.required ?? []).includes(prop);
      fields.push({
        name: goFieldName(prop),
        type: fieldGoType(propSchema, schemas, required),
        tag: required ? prop : prop + ',omitempty',
      });
    }
    // gofmt alignment: pad the name column to the longest name, then
    // the type column to the longest type (each +1 space).
    const nameWidth = Math.max(...fields.map((f) => f.name.length));
    const typeWidth = Math.max(...fields.map((f) => f.type.length));
    lines.push('type ' + name + ' struct {');
    for (const f of fields) {
      lines.push('\t' + f.name.padEnd(nameWidth) + ' ' + f.type.padEnd(typeWidth) + ' \`json:"' + f.tag + '"\`');
    }
    lines.push('}', '');
  }
  return lines.join('\\n');
}

// ---- client ----------------------------------------------------------------

function methodName(path) {
  // '/ai/vector-store/upsert' -> 'VectorStoreUpsert' (skip the /ai
  // root; non-alphanumeric segments are CamelCased and joined).
  const segs = path.split('/').filter(Boolean).slice(1);
  return segs
    .map((s) => s.split(/[^a-zA-Z0-9]/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(''))
    .join('');
}

function operationTypes(op, schemas) {
  const req = op.requestBody?.content?.['application/json']?.schema;
  const resp = op.responses?.['200']?.content?.['application/json']?.schema;
  return {
    reqName: req?.$ref ? req.$ref.split('/').pop() : null,
    respName: resp?.$ref ? resp.$ref.split('/').pop() : null,
  };
}

function generateClient(paths, schemas) {
  const lines = [];
  lines.push('// HTTPError carries a non-2xx response from the AI service.');
  lines.push('type HTTPError struct {');
  lines.push('\tStatus int');
  lines.push('\tBody   string');
  lines.push('}');
  lines.push('');
  lines.push('func (e *HTTPError) Error() string {');
  lines.push('\tif e.Body == "" {');
  lines.push('\t\treturn fmt.Sprintf("aiclient: %s", http.StatusText(e.Status))');
  lines.push('\t}');
  lines.push('\treturn fmt.Sprintf("aiclient: %s: %s", http.StatusText(e.Status), e.Body)');
  lines.push('}');
  lines.push('');
  lines.push('// Client is a typed Go client over the committed openapi.ai.yaml.');
  lines.push('type Client struct {');
  lines.push('\tbaseURL string');
  lines.push('\thttp    *http.Client');
  lines.push('}');
  lines.push('');
  lines.push('// NewClient wires a client to the AI service base URL, e.g.');
  lines.push('// http://localhost:3200 (AI_SERVICE_URL).');
  lines.push('func NewClient(baseURL string) *Client {');
  lines.push('\treturn &Client{baseURL: strings.TrimSuffix(baseURL, "/"), http: &http.Client{Timeout: 30 * time.Second}}');
  lines.push('}');
  lines.push('');
  lines.push('// do performs one JSON request/response round-trip.');
  lines.push('func (c *Client) do(ctx context.Context, method, path string, body, out any) error {');
  lines.push('\tvar reader io.Reader');
  lines.push('\tif body != nil {');
  lines.push('\t\traw, err := json.Marshal(body)');
  lines.push('\t\tif err != nil {');
  lines.push('\t\t\treturn fmt.Errorf("aiclient: marshal %s %s: %w", method, path, err)');
  lines.push('\t\t}');
  lines.push('\t\treader = bytes.NewReader(raw)');
  lines.push('\t}');
  lines.push('\treq, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, reader)');
  lines.push('\tif err != nil {');
  lines.push('\t\treturn fmt.Errorf("aiclient: %s %s: %w", method, path, err)');
  lines.push('\t}');
  lines.push('\tif body != nil {');
  lines.push('\t\treq.Header.Set("Content-Type", "application/json")');
  lines.push('\t}');
  lines.push('\tresp, err := c.http.Do(req)');
  lines.push('\tif err != nil {');
  lines.push('\t\treturn fmt.Errorf("aiclient: %s %s: %w", method, path, err)');
  lines.push('\t}');
  lines.push('\tdefer resp.Body.Close()');
  lines.push('\tif resp.StatusCode >= 400 {');
  lines.push('\t\traw, _ := io.ReadAll(resp.Body)');
  lines.push('\t\treturn &HTTPError{Status: resp.StatusCode, Body: strings.TrimSpace(string(raw))}');
  lines.push('\t}');
  lines.push('\tif out != nil {');
  lines.push('\t\tif err := json.NewDecoder(resp.Body).Decode(out); err != nil {');
  lines.push('\t\t\treturn fmt.Errorf("aiclient: decode %s %s: %w", method, path, err)');
  lines.push('\t\t}');
  lines.push('\t}');
  lines.push('\treturn nil');
  lines.push('}');
  lines.push('');
  for (const [path, item] of Object.entries(paths)) {
    for (const [method, op] of Object.entries(item)) {
      if (method !== 'post') continue;
      const { reqName, respName } = operationTypes(op, schemas);
      const name = methodName(path);
      lines.push('// ' + name.toUpperCase() + ' calls ' + method.toUpperCase() + ' ' + path + '.');
      lines.push('func (c *Client) ' + name + '(ctx context.Context, req ' + reqName + ') (*' + respName + ', error) {');
      lines.push('\tvar out ' + respName);
      lines.push('\tif err := c.do(ctx, http.MethodPost, "' + path + '", req, &out); err != nil {');
      lines.push('\t\treturn nil, err');
      lines.push('\t}');
      lines.push('\treturn &out, nil');
      lines.push('}');
      lines.push('');
    }
  }
  return lines.join('\\n');
}

// ---- emit ------------------------------------------------------------------

const schemas = spec.components?.schemas ?? {};
const paths = spec.paths ?? {};

const src = generateStructs(schemas) + '\\n' + generateClient(paths, schemas);

mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, 'client.go'), src);

console.log('generate-go-client: wrote ' + join(outDir, 'client.go'));
`;
}
