// goClientGo is the committed output of scripts/generate-go-client.mjs
// over the committed openapi.ai.yaml. test/generated-go.test.ts is the
// tripwire.
function goClientGo(): string {
  return `// GENERATED by scripts/generate-go-client.mjs — do not edit by hand.
// Regenerate with \`task contract:generate\` after regenerating
// openapi.ai.yaml from the Python service (decision 9: Python is
// the canonical side of the AI service contract).

package aiclient

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
)

// One completion candidate.
type ChatChoice struct {
	Index        int64       \`json:"index"\`
	Message      ChatMessage \`json:"message"\`
	FinishReason *string     \`json:"finish_reason,omitempty"\`
}

// The body of POST /ai/chat/completions.
type ChatCompletionRequest struct {
	Model       *string          \`json:"model,omitempty"\`
	Messages    []ChatMessage    \`json:"messages"\`
	Temperature *float64         \`json:"temperature,omitempty"\`
	Stream      bool             \`json:"stream,omitempty"\`
	Tools       []ToolDefinition \`json:"tools,omitempty"\`
	ToolChoice  *string          \`json:"tool_choice,omitempty"\`
}

// The body of POST /ai/chat/completions (stream=false).
type ChatCompletionResponse struct {
	Id      string       \`json:"id"\`
	Model   string       \`json:"model"\`
	Choices []ChatChoice \`json:"choices"\`
	Usage   *Usage       \`json:"usage,omitempty"\`
}

// One message of the conversation.
type ChatMessage struct {
	Role      string     \`json:"role"\`
	Content   *string    \`json:"content,omitempty"\`
	ToolCalls []ToolCall \`json:"tool_calls,omitempty"\`
}

// One embedded input.
type EmbeddingData struct {
	Embedding []float64 \`json:"embedding"\`
	Index     int64     \`json:"index"\`
}

// The body of POST /ai/embeddings.
type EmbeddingsRequest struct {
	Model *string \`json:"model,omitempty"\`
	Input any     \`json:"input"\`
}

// The body of POST /ai/embeddings.
type EmbeddingsResponse struct {
	Model string          \`json:"model"\`
	Data  []EmbeddingData \`json:"data"\`
}

// A concrete tool invocation returned by the model.
type ToolCall struct {
	Id        string \`json:"id"\`
	Name      string \`json:"name"\`
	Arguments string \`json:"arguments"\`
}

// A function the model may call (tool/function calling, decision 20).
type ToolDefinition struct {
	Name        string         \`json:"name"\`
	Description *string        \`json:"description,omitempty"\`
	Parameters  map[string]any \`json:"parameters,omitempty"\`
}

// Token accounting for a completion.
type Usage struct {
	PromptTokens     int64 \`json:"prompt_tokens"\`
	CompletionTokens int64 \`json:"completion_tokens"\`
	TotalTokens      int64 \`json:"total_tokens"\`
}

// A vector to store (upsert) or a stored vector's metadata.
type VectorRecord struct {
	Id       string         \`json:"id"\`
	Vector   []float64      \`json:"vector"\`
	Metadata map[string]any \`json:"metadata,omitempty"\`
}

// The body of POST /ai/vector-store/search.
type VectorStoreSearchRequest struct {
	Vector []float64 \`json:"vector"\`
	TopK   int64     \`json:"top_k,omitempty"\`
}

// The body of POST /ai/vector-store/search.
type VectorStoreSearchResponse struct {
	Results []VectorStoreSearchResult \`json:"results"\`
}

// One nearest-neighbour hit.
type VectorStoreSearchResult struct {
	Id       string         \`json:"id"\`
	Score    float64        \`json:"score"\`
	Metadata map[string]any \`json:"metadata,omitempty"\`
}

// The body of POST /ai/vector-store/upsert.
type VectorStoreUpsertRequest struct {
	Vectors []VectorRecord \`json:"vectors"\`
}

// The body of POST /ai/vector-store/upsert.
type VectorStoreUpsertResponse struct {
	Count int64 \`json:"count"\`
}

// HTTPError carries a non-2xx response from the AI service.
type HTTPError struct {
	Status int
	Body   string
}

func (e *HTTPError) Error() string {
	if e.Body == "" {
		return fmt.Sprintf("aiclient: %s", http.StatusText(e.Status))
	}
	return fmt.Sprintf("aiclient: %s: %s", http.StatusText(e.Status), e.Body)
}

// Client is a typed Go client over the committed openapi.ai.yaml.
type Client struct {
	baseURL string
	http    *http.Client
}

// NewClient wires a client to the AI service base URL, e.g.
// http://localhost:3200 (AI_SERVICE_URL).
func NewClient(baseURL string) *Client {
	return &Client{baseURL: strings.TrimSuffix(baseURL, "/"), http: &http.Client{Timeout: 30 * time.Second}}
}

// do performs one JSON request/response round-trip.
func (c *Client) do(ctx context.Context, method, path string, body, out any) error {
	var reader io.Reader
	if body != nil {
		raw, err := json.Marshal(body)
		if err != nil {
			return fmt.Errorf("aiclient: marshal %s %s: %w", method, path, err)
		}
		reader = bytes.NewReader(raw)
	}
	req, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, reader)
	if err != nil {
		return fmt.Errorf("aiclient: %s %s: %w", method, path, err)
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return fmt.Errorf("aiclient: %s %s: %w", method, path, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 400 {
		raw, _ := io.ReadAll(resp.Body)
		return &HTTPError{Status: resp.StatusCode, Body: strings.TrimSpace(string(raw))}
	}
	if out != nil {
		if err := json.NewDecoder(resp.Body).Decode(out); err != nil {
			return fmt.Errorf("aiclient: decode %s %s: %w", method, path, err)
		}
	}
	return nil
}

// CHATCOMPLETIONS calls POST /ai/chat/completions.
func (c *Client) ChatCompletions(ctx context.Context, req ChatCompletionRequest) (*ChatCompletionResponse, error) {
	var out ChatCompletionResponse
	if err := c.do(ctx, http.MethodPost, "/ai/chat/completions", req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// EMBEDDINGS calls POST /ai/embeddings.
func (c *Client) Embeddings(ctx context.Context, req EmbeddingsRequest) (*EmbeddingsResponse, error) {
	var out EmbeddingsResponse
	if err := c.do(ctx, http.MethodPost, "/ai/embeddings", req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// VECTORSTOREUPSERT calls POST /ai/vector-store/upsert.
func (c *Client) VectorStoreUpsert(ctx context.Context, req VectorStoreUpsertRequest) (*VectorStoreUpsertResponse, error) {
	var out VectorStoreUpsertResponse
	if err := c.do(ctx, http.MethodPost, "/ai/vector-store/upsert", req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// VECTORSTORESEARCH calls POST /ai/vector-store/search.
func (c *Client) VectorStoreSearch(ctx context.Context, req VectorStoreSearchRequest) (*VectorStoreSearchResponse, error) {
	var out VectorStoreSearchResponse
	if err := c.do(ctx, http.MethodPost, "/ai/vector-store/search", req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}
`;
}
function goClientReadme(): string {
  return `# clients/go — the generated Go client for the AI service

A stdlib-only Go client over the committed \`../openapi.ai.yaml\` — the
AI service's Python-generated spec (decision 9: Python is the
canonical side of the AI service's own contract). \`apps/api\` consumes
this client through a local \`go.mod\` replace:

    require starter/contract/ai-client v0.0.0
    replace starter/contract/ai-client => ../../packages/contract/clients/go

…and that is the ONLY way the Go api talks to apps/ai (decision 5: the
AI service is called by the Go api, never by the web app directly, and
never by raw HTTP in the api).

## Regenerating

The client is generated, never hand-edited:

1. Change the Python models in \`apps/ai/app/primitives/models.py\`.
2. \`task contract:generate\` — regenerates \`openapi.ai.yaml\` from the
   FastAPI app AND this client from the spec.
3. Commit the diff (the scaffold's tests tripwire this: the AI
   service's \`tests/test_contract.py\` proves the committed spec equals
   the live spec; \`test/generated-go.test.ts\` proves this client
   equals the generator's output).
`;
}
function generatedGoTestTs(): string {
  return `// test/generated-go.test.ts — proves the AI contract's
// Go-as-downstream rule holds in the scaffolded project (issue #16,
// decision 9/19 applied to the Python side): the committed Go client
// (clients/go/client.go) is byte-identical to what the committed
// generator produces from the committed openapi.ai.yaml. If the
// Python service's spec changes, \`task contract:generate\` must be run
// and its output committed — this test is the tripwire.
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { describe, expect, it } from 'vitest';

const contractDir = resolve(import.meta.dirname, '..');
const specPath = join(contractDir, 'openapi.ai.yaml');
const generator = join(contractDir, 'scripts/generate-go-client.mjs');
const committed = join(contractDir, 'clients/go/client.go');

describe('generated Go client is committed and up to date (issue #16, decision 9)', () => {
  it('regenerating from the committed openapi.ai.yaml changes nothing', () => {
    const out = mkdtempSync(join(tmpdir(), 'contract-go-regen-'));
    try {
      execFileSync(process.execPath, [generator, specPath, out], { stdio: 'pipe' });
      expect(
        readFileSync(join(out, 'client.go'), 'utf8'),
        'clients/go/client.go is stale — run \`task contract:generate\` and commit the diff',
      ).toBe(readFileSync(committed, 'utf8'));
    } finally {
      rmSync(out, { recursive: true, force: true });
    }
  });

  it('the client exposes the four composable primitives (decision 20)', () => {
    const client = readFileSync(committed, 'utf8');
    for (const m of ['ChatCompletions', 'Embeddings', 'VectorStoreUpsert', 'VectorStoreSearch']) {
      expect(client, \`client.go should expose \${m}\`).toContain(\`func (c *Client) \${m}(\`);
    }
  });
});
`;
}

