// generatedTestTsAi is the AI-on version of the contract package's
// generated.test.ts (the base shape-4 one is overwritten): the
// tripwire now covers the /ai proxy surface of the merged spine.
function generatedTestTsAi(): string {
  return `// test/generated.test.ts — proves the Go-as-canonical rule holds in
// the scaffolded project (decision 19) for shape 4 + AI on
// (Go-microservices with the Python/FastAPI AI service, issue #16):
// every committed artifact in this package is byte-identical to what
// the generation pipeline produces. If a spec changes, \`task
// contract:generate\` must be run and its output committed — this
// file is the tripwire.
//
//   1. openapi.yaml == merge(openapi.api.yaml, openapi.auth.yaml)
//      (the partials are themselves tripwired by each service's
//      contract_test.go against its live spec; openapi.ai.yaml is
//      tripwired by apps/ai's tests/test_contract.py, and the Go
//      client generated from it by test/generated-go.test.ts)
//   2. the committed TS client == the generator's output from the
//      merged openapi.yaml
//   3. the client covers every route of the merged spec (except
//      well-known infra endpoints, which no client consumes)
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { describe, expect, it } from 'vitest';

const contractDir = resolve(import.meta.dirname, '..');
const mergeScript = join(contractDir, 'scripts/merge-openapi.mjs');
const generator = join(contractDir, 'scripts/generate-ts-client.mjs');
const partials = {
  api: join(contractDir, 'openapi.api.yaml'),
  auth: join(contractDir, 'openapi.auth.yaml'),
};
const mergedSpec = join(contractDir, 'openapi.yaml');
const committed = {
  'types.ts': join(contractDir, 'src/types.ts'),
  'client.ts': join(contractDir, 'src/client.ts'),
  'index.ts': join(contractDir, 'src/index.ts'),
};

describe('the committed contract is generated, not hand-edited (decision 19, shape 4 + AI)', () => {
  it('the merged openapi.yaml equals the merge of the two committed partials', () => {
    const out = mkdtempSync(join(tmpdir(), 'contract-merge-'));
    try {
      execFileSync(process.execPath, [mergeScript, partials.api, partials.auth, join(out, 'merged.yaml')], {
        stdio: 'pipe',
      });
      expect(
        readFileSync(join(out, 'merged.yaml'), 'utf8'),
        \`openapi.yaml is stale — run \\\`task contract:generate\\\` and commit the diff\`,
      ).toBe(readFileSync(mergedSpec, 'utf8'));
    } finally {
      rmSync(out, { recursive: true, force: true });
    }
  });

  it('regenerating the TS client from the merged openapi.yaml changes nothing', () => {
    const out = mkdtempSync(join(tmpdir(), 'contract-regen-'));
    try {
      execFileSync(process.execPath, [generator, mergedSpec, out], { stdio: 'pipe' });
      for (const [name, committedPath] of Object.entries(committed)) {
        expect(readFileSync(join(out, name), 'utf8'), \`\${name} is stale — run \\\`task contract:generate\\\` and commit the diff\`)
          .toBe(readFileSync(committedPath, 'utf8'));
      }
    } finally {
      rmSync(out, { recursive: true, force: true });
    }
  });

  it('the client covers every route of the merged spec (well-known infra excluded)', () => {
    const client = readFileSync(committed['client.ts'], 'utf8');
    for (const ep of [
      '/items',
      '/auth/register',
      '/auth/login',
      '/auth/refresh',
      '/auth/logout',
      // Issue #16: the AI primitives reach the web through the api.
      '/ai/chat/completions',
      '/ai/embeddings',
      '/ai/vector-store/upsert',
      '/ai/vector-store/search',
    ]) {
      expect(client, \`client.ts should expose \${ep}\`).toContain(\`'\${ep}'\`);
    }
    // The JWKS endpoint is machine-to-machine infra consumed by the
    // api, not by generated clients — the generator skips well-known
    // paths, so the client must NOT contain it.
    expect(client).not.toContain('/.well-known');
    // The items routes are authenticated (Bearer) per the spec's
    // security requirement.
    expect(client).toMatch(/GET \\/items \\(requires Bearer access token\\)/);
  });
});
`;
}
